1. // Copyright(c) The Maintainers of Nanvix.
2. // Licensed under the MIT License.
3. 
4. //!
5. //! # Fixed-Size Bump Allocator
6. //!
7. //! A generic, `no_std`-compatible bump allocator that hands out fixed-size slots from a
8. //! statically reserved memory region (typically BSS). Each slot is allocated exactly once via an
9. //! atomic compare-and-swap index, making the allocator lock-free and safe for concurrent use.
10. //!
11. //! ## Key Types
12. //!
13. //! - [`BssStorage`] — unsafe trait implemented by the backing store provider.
14. //! - [`FixedSizeBumpAllocator`] — the allocator parameterised by unit size, alignment, and
15. //!   storage backend.
16. //! - [`BumpAllocError`] — error type returned when allocation fails.
17. //!
18. //! ## Usage
19. //!
20. //! 1. Define a static storage region and implement [`BssStorage`] for it.
21. //! 2. Create a `static` [`FixedSizeBumpAllocator`] with [`FixedSizeBumpAllocator::new()`].
22. //! 3. Call [`alloc()`](FixedSizeBumpAllocator::alloc) to obtain raw byte slots, or
23. //!    [`alloc_as()`](FixedSizeBumpAllocator::alloc_as) for typed `MaybeUninit<T>` slots.
24. //!
25. //! ## Example
26. //!
27. //! ```rust
28. //! use bump_allocator::{align_up, BssStorage, BumpAllocError, FixedSizeBumpAllocator};
29. //!
30. //! const UNIT_SIZE: usize = 64;
31. //! const UNIT_ALIGN: usize = 64;
32. //! const NUM_SLOTS: usize = 4;
33. //! const STRIDE: usize = match align_up(UNIT_SIZE, UNIT_ALIGN) {
34. //!     Some(v) => v,
35. //!     None => panic!("stride overflow"),
36. //! };
37. //! const STORAGE_SIZE: usize = NUM_SLOTS * STRIDE;
38. //!
39. //! #[repr(align(64))]
40. //! struct MyStorage {
41. //!     bytes: [u8; STORAGE_SIZE],
42. //! }
43. //!
44. //! static mut BACKING: MyStorage = MyStorage {
45. //!     bytes: [0; STORAGE_SIZE],
46. //! };
47. //!
48. //! struct MyBackend;
49. //!
50. //! // SAFETY: BACKING is a stable, properly aligned static region exclusively managed by
51. //! // the allocator.
52. //! unsafe impl BssStorage for MyBackend {
53. //!     const NUM_UNITS: usize = NUM_SLOTS;
54. //!     const STORAGE_SIZE: usize = STORAGE_SIZE;
55. //!
56. //!     fn as_mut_ptr() -> *mut u8 {
57. //!         unsafe { core::ptr::addr_of_mut!(BACKING.bytes) as *mut u8 }
58. //!     }
59. //! }
60. //!
61. //! // SAFETY: single allocator instance for `MyBackend`.
62. //! static ALLOCATOR: FixedSizeBumpAllocator<UNIT_SIZE, UNIT_ALIGN, MyBackend> =
63. //!     unsafe { FixedSizeBumpAllocator::new() };
64. //!
65. //! // Allocate raw byte slots.
66. //! let slot_a: &mut [u8; UNIT_SIZE] = ALLOCATOR.alloc().expect("slot a");
67. //! let slot_b: &mut [u8; UNIT_SIZE] = ALLOCATOR.alloc().expect("slot b");
68. //! assert_ne!(slot_a.as_ptr(), slot_b.as_ptr());
69. //!
70. //! // Allocate a typed slot (caller must initialise before reading).
71. //! let uninit: &mut core::mem::MaybeUninit<[u32; 16]> =
72. //!     unsafe { ALLOCATOR.alloc_as::<[u32; 16]>().expect("typed slot") };
73. //! uninit.write([0u32; 16]);
74. //! let typed: &mut [u32; 16] = unsafe { uninit.assume_init_mut() };
75. //! typed[0] = 42;
76. //! assert_eq!(typed[0], 42);
77. //! ```
78. 
79. //==================================================================================================
80. // Configuration
81. //==================================================================================================
82. 
83. #![cfg_attr(not(any(test, feature = "std")), no_std)]
84. 
85. //==================================================================================================
86. // Imports
87. //==================================================================================================
88. 
89. use ::core::{
90.     fmt,
91.     marker::PhantomData,
92.     mem::MaybeUninit,
93.     sync::atomic::{
94.         AtomicUsize,
95.         Ordering,
96.     },
97. };
98. use ::vstd::prelude::*;
99. 
100. // Include specifications.
101. #[cfg(verus_keep_ghost)]
102. include!("lib.spec.rs");
103. 
104. // Include proofs.
105. #[cfg(verus_keep_ghost)]
106. include!("lib.proof.rs");
107. 
108. //==================================================================================================
109. // Traits and Types
110. //==================================================================================================
111. 
112. ///
113. /// # Description
114. ///
115. /// Aligns `value` up to the next multiple of `alignment`.
116. ///
117. /// # Parameters
118. ///
119. /// - `value`: Value to align.
120. /// - `alignment`: Alignment boundary.
121. ///
122. /// # Returns
123. ///
124. /// Returns the aligned value, or `None` if `alignment` is zero or the computation overflows.
125. ///
126. #[verus_spec(result =>
127.     ensures
128.         match result {
129.             Some(r) => align_up_spec(value as nat, alignment as nat) == Some(r as nat),
130.             None => align_up_spec(value as nat, alignment as nat) is None,
131.         },
132. )]
133. pub const fn align_up(value: usize, alignment: usize) -> Option<usize> {
134.     if alignment == 0 {
135.         return None;
136.     }
137.     value.div_ceil(alignment).checked_mul(alignment)
138. }
139. 
140. ///
141. /// # Description
142. ///
143. /// Error type returned by [`FixedSizeBumpAllocator`] operations.
144. ///
145. #[derive(Debug, Clone, Copy, PartialEq, Eq)]
146. #[verus_verify]
147. pub enum BumpAllocError {
148.     /// Storage capacity exhausted.
149.     Exhausted,
150.     /// Type size does not match allocator unit size.
151.     SizeMismatch,
152.     /// Type alignment exceeds allocator alignment.
153.     AlignmentMismatch,
154.     /// Internal arithmetic overflow.
155.     Overflow,
156.     /// Computed slot exceeds storage bounds.
157.     OutOfBounds,
158.     /// Computed slot is not properly aligned.
159.     Misaligned,
160. }
161. 
162. impl fmt::Display for BumpAllocError {
163.     fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
164.         match self {
165.             Self::Exhausted => write!(f, "fixed-size BSS allocator exhausted"),
166.             Self::SizeMismatch => write!(f, "type size does not match allocator unit size"),
167.             Self::AlignmentMismatch => write!(f, "type alignment exceeds allocator alignment"),
168.             Self::Overflow => write!(f, "allocator internal arithmetic overflow"),
169.             Self::OutOfBounds => write!(f, "allocator slot exceeds storage bounds"),
170.             Self::Misaligned => write!(f, "allocator returned misaligned slot"),
171.         }
172.     }
173. }
174. 
175. ///
176. /// # Description
177. ///
178. /// Backend trait for fixed-size allocators that draw memory from static storage.
179. ///
180. /// # Safety
181. ///
182. /// Implementers must guarantee that:
183. ///
184. /// - `as_mut_ptr()` returns a stable pointer to a backing region of at least `STORAGE_SIZE`
185. ///   bytes for the allocator lifetime.
186. /// - the backing region is writable and properly aligned for any allocation site that uses this
187. ///   backend.
188. /// - the backing region is exclusively managed by this allocator API, so creating `&'static mut`
189. ///   references from slots cannot alias with other mutable references.
190. ///
191. #[verus_verify]
192. pub unsafe trait BssStorage {
193.     /// Number of fixed-size units that can be allocated.
194.     const NUM_UNITS: usize;
195. 
196.     /// Total size in bytes of the backing storage region.
197.     const STORAGE_SIZE: usize;
198. 
199.     /// Returns a mutable pointer to the beginning of the storage region.
200.     #[verus_spec(result =>
201.         ensures
202.             result as int == base_of::<Self>(),
203.     )]
204.     fn as_mut_ptr() -> *mut u8;
205. }
206. 
207. ///
208. /// # Description
209. ///
210. /// Generic fixed-size bump allocator over statically reserved memory.
211. ///
212. /// # Type Parameters
213. ///
214. /// - `N`: Unit size in bytes.
215. /// - `A`: Unit alignment in bytes.
216. /// - `S`: Backing storage provider.
217. ///
218. #[verus_verify]
219. pub struct FixedSizeBumpAllocator<const N: usize, const A: usize, S: BssStorage> {
220.     /// Atomic bump index for the next available slot.
221.     next_slot: AtomicUsize,
222.     /// Marker for the backend storage provider.
223.     _storage: PhantomData<S>,
224. }
225. 
226. impl<const N: usize, const A: usize, S: BssStorage> FixedSizeBumpAllocator<N, A, S> {
227.     ///
228.     /// # Description
229.     ///
230.     /// Creates a new fixed-size bump allocator.
231.     ///
232.     /// # Returns
233.     ///
234.     /// Returns a new allocator.
235.     ///
236.     /// # Safety
237.     ///
238.     /// The caller must ensure that only **one** `FixedSizeBumpAllocator` instance exists for a
239.     /// given `S: BssStorage` backend at any time. Creating multiple allocators over the same
240.     /// backend causes independent bump counters, which leads to overlapping slot reservations
241.     /// and undefined behavior (multiple `&'static mut` references to the same memory).
242.     ///
243.     pub const unsafe fn new() -> Self {
244.         Self {
245.             next_slot: AtomicUsize::new(0),
246.             _storage: PhantomData,
247.         }
248.     }
249. 
250.     ///
251.     /// # Description
252.     ///
253.     /// Allocates the next fixed-size slot as a raw byte array.
254.     ///
255.     /// # Returns
256.     ///
257.     /// On success, returns a mutable reference to a unit-sized byte array.
258.     ///
259.     /// # Errors
260.     ///
261.     /// - [`BumpAllocError::Exhausted`] if storage capacity is exhausted.
262.     /// - [`BumpAllocError::Overflow`] if internal arithmetic overflows.
263.     /// - [`BumpAllocError::OutOfBounds`] if computed slot exceeds storage bounds.
264.     /// - [`BumpAllocError::Misaligned`] if computed slot is not properly aligned.
265.     ///
266.     // SAFETY-SPEC: `external_body` because the success path materializes a
267.     // `&'static mut [u8; N]` from a backend-provided address (`usize as *mut`), a
268.     // raw-memory operation Verus cannot verify without a `PointsTo` permission for
269.     // the externally-owned `BssStorage` region. Mirrors the `src/libs/raw-array`
270.     // pattern. Registered in `verus-ai-logs/tcb-allowed.md`.
271.     #[verus_spec(result =>
272.         requires bump_view(self).inv(),
273.         ensures
274.             match result {
275.                 Ok(slot) => {
276.                     let v = bump_view(self);
277.                     let a = slot_ref_addr(slot);
278.                     &&& a % (v.unit_align as int) == 0
279.                     &&& v.base <= a
280.                     &&& a + (N as int) <= v.base + (v.storage_size as int)
281.                 },
282.                 Err(_) => true,
283.             },
284.     )]
285.     pub fn alloc(&self) -> Result<&'static mut [u8; N], BumpAllocError> {
286.         // Reserve a slot index via compare-and-swap to avoid overshooting the counter.
287.         let idx: usize = loop {
288.             let current: usize = self.next_slot.load(Ordering::Acquire);
289.             if current >= S::NUM_UNITS {
290.                 return Err(BumpAllocError::Exhausted);
291.             }
292.             let next: usize = current.checked_add(1).ok_or(BumpAllocError::Overflow)?;
293.             if self
294.                 .next_slot
295.                 .compare_exchange(current, next, Ordering::AcqRel, Ordering::Acquire)
296.                 .is_ok()
297.             {
298.                 break current;
299.             }
300.         };
301. 
302.         let stride: usize = align_up(N, A).ok_or(BumpAllocError::Overflow)?;
303.         let offset: usize = idx.checked_mul(stride).ok_or(BumpAllocError::Overflow)?;
304. 
305.         let base: usize = S::as_mut_ptr() as usize;
306.         let ptr: usize = base.checked_add(offset).ok_or(BumpAllocError::Overflow)?;
307.         let end: usize = ptr.checked_add(N).ok_or(BumpAllocError::Overflow)?;
308.         let storage_end: usize = base
309.             .checked_add(S::STORAGE_SIZE)
310.             .ok_or(BumpAllocError::Overflow)?;
311.         if end > storage_end {
312.             return Err(BumpAllocError::OutOfBounds);
313.         }
314.         if !ptr.is_multiple_of(A) {
315.             return Err(BumpAllocError::Misaligned);
316.         }
317. 
318.         // SAFETY: the backend contract guarantees valid stable storage; each slot index is handed
319.         // out at most once by atomic compare-and-swap.
320.         Ok(unsafe { &mut *(ptr as *mut [u8; N]) })
321.     }
322. 
323.     ///
324.     /// # Description
325.     ///
326.     /// Allocates the next fixed-size slot and reinterprets it as `MaybeUninit<T>`.
327.     ///
328.     /// # Returns
329.     ///
330.     /// On success, returns a mutable reference to an uninitialized `T`.
331.     ///
332.     /// # Errors
333.     ///
334.     /// - [`BumpAllocError::SizeMismatch`] if `size_of::<T>() != N`.
335.     /// - [`BumpAllocError::AlignmentMismatch`] if `align_of::<T>() > A`.
336.     /// - Any error from [`alloc()`](Self::alloc).
337.     ///
338.     /// # Safety
339.     ///
340.     /// The caller must initialise the returned `MaybeUninit<T>` before reading through it
341.     /// and ensure exclusive use of the returned reference.
342.     ///
343.     // SAFETY-SPEC: `external_body` for the same reason as `alloc` (it delegates to
344.     // `alloc` and then re-materializes the slot reference as `&'static mut
345.     // MaybeUninit<T>`). The size/alignment guard arms make the `T`-vs-`(N, A)`
346.     // contract caller-visible. Registered in `verus-ai-logs/tcb-allowed.md`.
347.     #[verus_spec(result =>
348.         requires bump_view(self).inv(),
349.         ensures
350.             match result {
351.                 Ok(slot) => {
352.                     let v = bump_view(self);
