     requires
         x <= xbound,
         y <= ybound,
         0 <= x,
         0 <= y,
     ensures
         #[trigger] (x * y) <= #[trigger] (xbound * ybound),
 {
     lemma_mul_inequality(x, xbound, y);
     lemma_mul_inequality(y, ybound, xbound);
 }

